import{_ as a,o as t,c as s,a8 as r}from"./chunks/framework.OOVqYmW6.js";const u=JSON.parse(`{"title":"What Rust Does—and Does Not—Protect","description":"Understand Rust's memory-safety guarantees and the application security risks that still need engineering controls.","frontmatter":{"requestedLanguage":"fr","contentLanguage":"en","languageFallbackNotice":"Cette page n’est pas disponible en Français. La version English est affichée.","sidebarTitle":"Rust Boundaries","icon":"rust","title":"What Rust Does—and Does Not—Protect","description":"Understand Rust's memory-safety guarantees and the application security risks that still need engineering controls.","summary":"Explains which memory-safety errors safe Rust helps prevent and why Rust does not automatically secure an application. It reviews injection, authentication and authorization, cryptography, web attacks, resource exhaustion, deserialization, unsafe code, dependencies, and business logic, then gives a practical model and further reading.","date":"2026-10-29T00:00:00.000Z","lastmod":"2026-10-29T00:00:00.000Z","weight":4,"status":"Exploring","tags":["feluqa","security","rust","memory-safety"],"draft":true,"author":{"name":"El Moumen Yassine","url":"https://numerimondes.com","linkedin":"https://www.linkedin.com/in/elmoumenyassine","email":"yassine@numerimondes.com"}},"headers":[],"relativePath":"fr/security/rust-security-boundaries.md","filePath":"fr/security/rust-security-boundaries.md"}`),n={name:"fr/security/rust-security-boundaries.md"};function i(o,e,l,d,c,h){return t(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="what-rust-does—and-does-not—protect" tabindex="-1">What Rust Does—and Does Not—Protect <a class="header-anchor" href="#what-rust-does—and-does-not—protect" aria-label="Permalink to &quot;What Rust Does—and Does Not—Protect&quot;">​</a></h1><p>Rust&#39;s ownership, borrowing, and type systems prevent many memory-safety errors in safe Rust. That is a major security benefit, but it does <strong>not</strong> make an application automatically secure. Application logic, configuration, dependencies, unsafe code, and the way the program handles untrusted input still matter.</p><h2 id="memory-safety-errors-that-safe-rust-helps-prevent" tabindex="-1">Memory-safety errors that safe Rust helps prevent <a class="header-anchor" href="#memory-safety-errors-that-safe-rust-helps-prevent" aria-label="Permalink to &quot;Memory-safety errors that safe Rust helps prevent&quot;">​</a></h2><p>Safe Rust&#39;s compile-time rules make many common memory-corruption errors unrepresentable in safe code, including:</p><ul><li>use-after-free, dangling references, and double frees;</li><li>out-of-bounds memory access through ordinary safe indexing (an invalid index can panic, but safe indexing does not become an unchecked memory write);</li><li>null references: Rust references cannot be null, and <code>Option&lt;T&gt;</code> represents an optional value explicitly;</li><li>data races in safe concurrent code.</li></ul><p>These guarantees depend on the soundness of unsafe code, foreign-function interfaces (FFI), and the libraries the application uses. The Rust compiler does not verify that an unsafe abstraction or an external library is sound.</p><h2 id="security-risks-rust-does-not-remove" tabindex="-1">Security risks Rust does not remove <a class="header-anchor" href="#security-risks-rust-does-not-remove" aria-label="Permalink to &quot;Security risks Rust does not remove&quot;">​</a></h2><h3 id="injection" tabindex="-1">Injection <a class="header-anchor" href="#injection" aria-label="Permalink to &quot;Injection&quot;">​</a></h3><p>Rust does not prevent untrusted data from being interpreted as SQL, a shell command, a directory path, or another language. Building a query by inserting input into a string is dangerous if the resulting string is executed as SQL:</p><div class="language-rust vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> query </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> format!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;SELECT id FROM users WHERE name = &#39;{username}&#39;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Use a parameterized query API, and validate input for the application&#39;s business rules. Apply the same principle to operating-system commands: prefer APIs that avoid a shell and pass validated arguments separately.</p><h3 id="authentication-and-authorization" tabindex="-1">Authentication and authorization <a class="header-anchor" href="#authentication-and-authorization" aria-label="Permalink to &quot;Authentication and authorization&quot;">​</a></h3><p>Logging a person in does not authorize every action they can reach. Check permissions and resource ownership on the server for each protected operation; do not rely on hidden buttons or client-side role checks.</p><div class="language-rust vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">is_authenticated</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // Authentication alone does not authorize this operation.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    delete_all_records</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Password reset, session management, role changes, and tenant boundaries also need explicit design and review. See the <a href="/fr/security/authorization-model">authorization model</a>.</p><h3 id="cryptography-and-secrets" tabindex="-1">Cryptography and secrets <a class="header-anchor" href="#cryptography-and-secrets" aria-label="Permalink to &quot;Cryptography and secrets&quot;">​</a></h3><p>Rust does not choose sound cryptographic protocols or protect secrets that developers hard-code, log, or expose to clients. Use maintained cryptographic libraries, established protocols, appropriate random sources, and approved secret storage. Do not implement cryptographic primitives yourself.</p><h3 id="cross-site-scripting-xss-and-request-forgery-csrf" tabindex="-1">Cross-site scripting (XSS) and request forgery (CSRF) <a class="header-anchor" href="#cross-site-scripting-xss-and-request-forgery-csrf" aria-label="Permalink to &quot;Cross-site scripting (XSS) and request forgery (CSRF)&quot;">​</a></h3><p>Web applications still need context-appropriate output escaping and safe handling of URLs and raw HTML. A formatting operation such as <code>format!(&quot;&lt;div&gt;{input}&lt;/div&gt;&quot;)</code> does not escape HTML. State-changing browser requests also need CSRF defenses appropriate to the application&#39;s session and request model.</p><h3 id="server-side-request-forgery-ssrf" tabindex="-1">Server-side request forgery (SSRF) <a class="header-anchor" href="#server-side-request-forgery-ssrf" aria-label="Permalink to &quot;Server-side request forgery (SSRF)&quot;">​</a></h3><p>If a server fetches a URL influenced by a user, it may be tricked into contacting internal services or other protected network addresses. Validate and allowlist destinations where possible, control redirects, and apply network-level restrictions as a second layer.</p><h3 id="denial-of-service-and-resource-exhaustion" tabindex="-1">Denial of service and resource exhaustion <a class="header-anchor" href="#denial-of-service-and-resource-exhaustion" aria-label="Permalink to &quot;Denial of service and resource exhaustion&quot;">​</a></h3><p>Memory safety is not resource safety. An attacker may send oversized requests, trigger expensive work, create excessive concurrency, or cause repeated allocation. Set limits for request bodies, time, concurrency, memory, and other resources that matter to the application. A panic caused by untrusted input may also disrupt a task or process, depending on how the application handles panics.</p><h3 id="deserialization-and-validation" tabindex="-1">Deserialization and validation <a class="header-anchor" href="#deserialization-and-validation" aria-label="Permalink to &quot;Deserialization and validation&quot;">​</a></h3><p>Parsing untrusted input into a Rust type does not prove that its values are valid for the business operation. Bound input size and nesting where relevant, validate invariants after parsing, and authorize the requested action. Data formats and deserializers have different security properties; select and configure them deliberately.</p><h3 id="unsafe-rust-ffi-and-dependencies" tabindex="-1">Unsafe Rust, FFI, and dependencies <a class="header-anchor" href="#unsafe-rust-ffi-and-dependencies" aria-label="Permalink to &quot;Unsafe Rust, FFI, and dependencies&quot;">​</a></h3><p><code>unsafe</code> blocks and FFI boundaries carry obligations that the compiler cannot prove. Keep them small, document their safety invariants, and review them carefully. Safe code can also depend on an unsound library. Review dependency ownership, maintenance, features, and known vulnerabilities; pin and audit the dependency graph according to the project&#39;s supply-chain policy.</p><h3 id="business-logic-and-logical-races" tabindex="-1">Business logic and logical races <a class="header-anchor" href="#business-logic-and-logical-races" aria-label="Permalink to &quot;Business logic and logical races&quot;">​</a></h3><p>Rust&#39;s data-race guarantees do not prove that a business operation is correct under concurrent requests. Duplicate transfers, replayed actions, skipped approval steps, and race conditions between checking and changing a record remain possible. Use transactions, idempotency controls, server-side policy checks, and tests that reflect the application&#39;s rules.</p><h2 id="a-useful-mental-model" tabindex="-1">A useful mental model <a class="header-anchor" href="#a-useful-mental-model" aria-label="Permalink to &quot;A useful mental model&quot;">​</a></h2><p>Rust helps protect memory integrity and prevents data races in safe concurrent code. It does not by itself provide authentication, authorization, correct business rules, injection defenses, secure cryptography, safe configuration, supply-chain integrity, or availability under attack. Treat these as separate security requirements and verify them at application and deployment level.</p><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://doc.rust-lang.org/reference/behavior-considered-undefined.html" target="_blank" rel="noreferrer">Rust Reference: behavior considered undefined</a></li><li><a href="https://doc.rust-lang.org/reference/unsafety.html" target="_blank" rel="noreferrer">Rust Reference: unsafety</a></li><li><a href="https://cheatsheetseries.owasp.org/cheatsheets/Injection_Prevention_Cheat_Sheet.html" target="_blank" rel="noreferrer">OWASP Injection Prevention Cheat Sheet</a></li><li><a href="https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html" target="_blank" rel="noreferrer">OWASP Authorization Cheat Sheet</a></li><li><a href="https://cheatsheetseries.owasp.org/cheatsheets/Cross_Site_Scripting_Prevention_Cheat_Sheet.html" target="_blank" rel="noreferrer">OWASP Cross-Site Scripting Prevention Cheat Sheet</a></li><li><a href="https://cheatsheetseries.owasp.org/cheatsheets/Cross-Site_Request_Forgery_Prevention_Cheat_Sheet.html" target="_blank" rel="noreferrer">OWASP Cross-Site Request Forgery Prevention Cheat Sheet</a></li><li><a href="https://cheatsheetseries.owasp.org/cheatsheets/Server_Side_Request_Forgery_Prevention_Cheat_Sheet.html" target="_blank" rel="noreferrer">OWASP Server-Side Request Forgery Prevention Cheat Sheet</a></li><li><a href="https://cheatsheetseries.owasp.org/cheatsheets/Denial_of_Service_Cheat_Sheet.html" target="_blank" rel="noreferrer">OWASP Denial of Service Cheat Sheet</a></li><li><a href="https://cheatsheetseries.owasp.org/cheatsheets/Deserialization_Cheat_Sheet.html" target="_blank" rel="noreferrer">OWASP Deserialization Cheat Sheet</a></li></ul>`,33)])])}const f=a(n,[["render",i]]);export{u as __pageData,f as default};
